  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Painike ei tee mitään? Valitse <b>Kopioi asetus sen sijaan</b>, suorita komentopaletista <b>MCP: Open User Configuration</b> ja liitä se sinne. VS Code käyttää avainta <code>servers</code>, ei <code>mcpServers</code>.",
