  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Keskustele valitsemasi mallin kanssa; {mnemo} lukee, kirjoittaa, tunnistaa, linkittää, siirtää ja siistii muistiinpanoja Memoran omilla työkaluilla. Se ei voi selata verkkoa, ajaa komentoja, poistaa lopullisesti tai muuttaa palvelinta. Avaimet suljetaan tälle palvelimelle eikä niitä koskaan lähetetä selaimeen.",
