  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude ja ChatGPT kirjautuvat Memora-tililläsi. Ei kopioitavaa.",
  "Claude models": "Claude-mallit",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude kirjautuu OAuthilla, joten avainta ei liitetä: se saa oman avaimen, kun painat Salli. Ilman kirjautumista yhdistä se kohdassa <b>Muu sovellus</b> ja lähetä otsikko <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor ja muut",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor ja muut, kullakin oma avain",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex ja muut saavat kukin oman käyttönsä, joten näet, mitä kukin tekee.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT ja oma agenttisi jakavat yhden Memoran, joka on tavoitettavissa tältä tietokoneelta, paikallisverkosta tai internetistä",
