  "Deleted": "Poistettu",
  "Deleted by {who}": "Poistanut {who}",
  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Poistetut keskustelut ja niiden viestit häviävät lopullisesti. Muistiinpanoihisi ei kosketa, ja parhaillaan vastaavaan keskusteluun ei kosketa.",
  "Deleted notes": "Poistetut muistiinpanot",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Poistetut muistiinpanot odottavat täällä, kunnes palautat tai poistat ne lopullisesti. Palauttaessasi valitset, minne muistiinpano menee: vanhaan kansioonsa, toiseen kansioon tai ylätasolle.",
