  "Done. I tagged 6 notes with #reading and linked 2 of them to {note}.": "Valmis. Merkitsin 6 muistiinpanoa tunnisteella #reading ja linkitin 2 niistä kohteeseen {note}.",
  "Dot grid": "Pistekuvio",
