  "Download the {kind} file": "Lataa {kind}-tiedosto",
  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Siirrä muistiinpano levyllä vetämällä kortti toisen kansion kehykseen. Järjestä taulu vetämällä kehystä sen nimestä; pudota se toisen kehyksen päälle siirtääksesi koko kansion sinne. Nimeä uudelleen kaksoisnapsauttamalla otsikkoa. Kosketuksella: vedä panoroidaksesi, nipistä zoomataksesi, siirrä korttia pitkällä painalluksella, esikatsele napauttamalla.",
  "Drag a note here to pin it": "Vedä muistiinpano tähän kiinnittääksesi sen",
  "Drag notes or folders here to pin them": "Vedä muistiinpanoja tai kansioita tähän kiinnittääksesi ne",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Siirrä muistiinpanoja tai kansioita vetämällä ne kansion päälle, kiinnitä vetämällä Kiinnitetyt-kohtaan.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Vedä muistiinpanoja · kaksoisnapsauta kiinnittääksesi · / haku · #tag etsii tunnisteita · F sovita · 1 2 3 asettelut",
  "Drag to move the folder frame; double-click to rename": "Siirrä kansion kehystä vetämällä; nimeä uudelleen kaksoisnapsauttamalla",
  "Drag to resize · double-click to reset": "Muuta kokoa vetämällä · palauta kaksoisnapsauttamalla",
  "Drag to turn · scroll to zoom · click a point to open its note": "Käännä vetämällä · zoomaa vierittämällä · avaa muistiinpano napsauttamalla pistettä",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Käännä vetämällä · zoomaa vierittämällä · avaa muistiinpano napsauttamalla pistettä · / hakuun · #tag etsii tunnisteita",
  "Draw a chart of how many notes I write each week": "Piirrä kaavio siitä, kuinka monta muistiinpanoa kirjoitan viikoittain",
  "Draw this note as a diagram": "Piirrä tämä muistiinpano kaaviona",
  "Drop here to hide": "Pudota tähän piilottaaksesi",
  "Drop on a folder": "Pudota kansion päälle",
  "Duplicated a note": "Monisti muistiinpanon",
  "Duration": "Kesto",
  "Dusk": "Hämärä",
  "Dyslexic": "Lukihäiriöystävällinen",
  "Each AI app connects over MCP with its own key and permissions.": "Jokainen tekoälysovellus yhdistyy MCP:llä omalla avaimellaan ja oikeuksillaan.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Jokainen yhdistämäsi tekoälysovellus on agentti omalla avaimellaan, joten näet mitä kukin tekee ja voit kytkeä yhden pois erikseen.",
  "Each agent": "Jokainen agentti",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Jokainen agentti kuuluu yhdelle sovellukselle. Toista sovellusta tai laitetta varten luo uusi agentti.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Jokainen agentti kuuluu yhdelle sovellukselle. Käyttääksesi Memoraa toisessa sovelluksessa luo sille oma agentti.",
  "Each app gets its own key": "Jokainen sovellus saa oman avaimen",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Jokaisella on lyhyt tunnus, joka ei koskaan muutu, joten nimiä voi vaihtaa vapaasti. Mnemo luo ne, muuttaa niiden ohjeita tai mallia, viestii niille, odottaa, pysäyttää, päättää ja poistaa ne, yksitellen tai kaikki kerralla, ja voi antaa niiden työskennellä taustalla. Jokainen kortti näyttää tehtävänannon, toiminnan ja vastauksen.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Jokaista lajia verrataan sen omaan tilaan: rajaan, jos se on asetettu, muuten käytettyyn määrään plus vapaa levytila{disk}. Tyhjä raja: ei rajaa.",
  "Each one gets its own key from Memora.": "Jokainen saa Memoralta oman avaimen.",
  "Earlier": "Aiemmin",
  "Earlier version": "Aiempi versio",
  "Edit": "Muokkaa",
  "Edit (E)": "Muokkaa (E)",
  "Edit folder rule": "Muokkaa kansiosääntöä",
