  "Empty the Trash?": "Tyhjennetäänkö Roskakori?",
  "Empty trash": "Tyhjennä Roskakori",
  "End every session except this one. Those browsers must sign in again.": "Lopeta kaikki istunnot paitsi tämä. Niiden selaimet joutuvat kirjautumaan uudelleen.",
  "End group": "Lopeta ryhmä",
  "End the pause on the server": "Lopeta tauko palvelimella",
  "End the session in this browser": "Lopeta istunto tässä selaimessa",
  "End the session in this browser.": "Lopeta istunto tässä selaimessa.",
  "Enter a username.": "Anna käyttäjänimi.",
  "Enter an address or a web address first.": "Anna ensin osoite tai verkko-osoite.",
  "Enter an address or a web address, then test.": "Anna osoite tai verkko-osoite ja testaa sitten.",
  "Enter the code here": "Anna koodi tähän",
  "Enter the folder path.": "Anna kansion polku.",
  "Enter the reset code": "Anna palautuskoodi",
  "Enter the setup code": "Anna asennuskoodi",
  "Enter your Memora password": "Anna Memora-salasanasi",
  "Enter your current password.": "Anna nykyinen salasanasi.",
  "Enter your password": "Anna salasanasi",
  "Entries": "Merkinnät",
  "Error": "Virhe",
  "Error 404": "Virhe 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Päivittäisessäkin käytössä selain kirjautuu uudelleen tämän ajan kuluttua. Se ei voi olla lyhyempi kuin passiivisuusaika.",
  "Every AI loses {n} tool at once. Asks first.": "Jokainen tekoäly menettää {n} työkalun kerralla. Kysyy ensin.",
  "Every AI loses {n} tools at once. Asks first.": "Jokainen tekoäly menettää {n} työkalua kerralla. Kysyy ensin.",
  "Every action, newest first": "Kaikki toiminnot, uusin ensin",
  "Every action, newest first, with search and filters.": "Kaikki toiminnot, uusin ensin, hakuineen ja suodattimineen.",
  "Every address from one to another.": "Jokainen osoite yhdestä toiseen.",
  "Every address from the first to the last, joined by a dash.": "Jokainen osoite ensimmäisestä viimeiseen, yhdistettynä viivalla.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Jokainen agentti aloittaa yleensä tyhjästä. {bold} yhdistä jokainen agentti kerran, niin ne kaikki lukevat samaa holvia ja kirjoittavat siihen, joten mitä yksi oppii, muut voivat käyttää.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Kaikki selaimet ja agentit katkaistaan, kunnes joku käynnistää Memoran uudelleen sillä koneella. Tämä sivu ei voi käynnistää sitä uudelleen.",
  "Every call shows up live in the brain and Activity": "Jokainen kutsu näkyy livenä aivoissa ja Toiminnassa",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Jokainen Mnemon tekemä muutos näkyy Toiminnassa ja sen voi kumota Historiasta.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Jokainen muutos, sinun tai sovelluksen tekemä, näkyy Toiminnassa ja sen voi kumota Historiasta.",
  "Every chat is archived.": "Jokainen keskustelu on arkistoitu.",
  "Every chat with your notes agent": "Jokainen keskustelu muistiinpanoagenttisi kanssa",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Jokainen yhdistetty tekoäly menettää kaikki {n} työkalua kerralla eikä voi enää lukea tai muuttaa muistiinpanojasi, ennen kuin kytket työkalut takaisin päälle täällä.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Jokainen yhdistetty tekoäly menettää sen kerralla. Voit kytkeä sen takaisin milloin vain.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Jokainen yhdistetty tekoäly menettää ne kerralla. Voit kytkeä ne takaisin milloin vain.",
  "Every connected agent loses its memory until Memora runs again.": "Jokainen yhdistetty agentti menettää muistinsa, kunnes Memora käynnistyy uudelleen.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Jokainen laite koti- tai toimistoverkossa, kirjoitettuna muodossa osoite/koko: 192.168.1.0/24 kattaa osoitteet 192.168.1.0–192.168.1.255.",
  "Every device on a home or office network.": "Jokainen laite koti- tai toimistoverkossa.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Jokainen muistiinpanokansion kuva ja missä se näkyy, sekä Mnemo-keskusteluille tallennetut kuvat.",
  "Every image is used in a note.": "Jokaista kuvaa käytetään muistiinpanossa.",
  "Every note": "Jokainen muistiinpano",
  "Every note and link, in 3D, as a graph or on a board.": "Jokainen muistiinpano ja linkki 3D:nä, graafina tai taululla.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Jokainen muistiinpano ja alikansio kansiossa \"{path}\" siirtyy kansioon {folder}; \"{name}\" poistetaan sitten. Jos nimi on siellä jo käytössä, siihen lisätään numero.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Jokaisesta muistiinpanosta tulee tähän kortti sen kansion kehykseen. Opas näyttää, miten tekoäly tallentaa tietonsa tänne tai miten kirjoitat muistiinpanon itse.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Jokaisesta muistiinpanosta tulee tähän valopiste, ryhmiteltynä kansioittain. Opas näyttää, miten tekoäly tallentaa tietonsa tänne tai miten kirjoitat muistiinpanon itse.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Jokainen tunnisteella #{tag} merkitty muistiinpano ({notes}) saa uuden nimen, myös tekstin sisäiset #tunnisteet.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Jokainen tunnisteilla {tags} merkitty muistiinpano saa yhden tunnisteen tilalle ({notes}). Tekstin sisäiset #tunnisteet muuttuvat myös. Yhden vaiheen kumoamista ei ole; jokainen muistiinpano säilyttää historiansa.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Jokainen agentin lukeminen ja kirjoitus näkyy livenä, joten tiedät aina kuka teki mitä.",
  "Every request that reaches this rule is {verb}.": "Jokainen tähän sääntöön osuva pyyntö {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Jokainen pyyntö. Aseta tämä viimeiseksi poimimaan se, mitä yllä olevat säännöt eivät kattaneet.",
  "Every setting and where it lives.": "Jokainen asetus ja missä se sijaitsee.",
  "Every shortcut in the web UI.": "Jokainen verkkokäyttöliittymän pikanäppäin.",
  "Every tag and its notes": "Jokainen tunniste ja sen muistiinpanot",
  "Every tool agents can call": "Jokainen työkalu, jota agentit voivat kutsua",
  "Every tool that is on for the server, including new ones.": "Jokainen työkalu, joka on päällä palvelimelle, uudet mukaan lukien.",
  "Everyone": "Kaikki",
  "Everything but your agents changes with the folder": "Kaikki paitsi agenttisi muuttuu kansion mukana",
  "Everything else": "Kaikki muu",
  "Everything in one folder": "Kaikki yhdessä kansiossa",
  "Everything in {vault}": "Kaikki kohteessa {vault}",
  "Everything is refused": "Kaikki hylätään",
