  "General": "Yleiset",
  "Get a one-time code on the server": "Hae kertakäyttökoodi palvelimelta",
  "Get started": "Aloita",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Tutustu minuun muistiinpanojeni kautta. Käy läpi holvini (viimeisimmät muistiinpanot, päiväkirjat, projektit, kaikki minusta) ja tallenna oppimasi remember_owner-työkalulla: kuka olen, mitä teen, millaisia vastauksia haluan, mistä pidän. Vain lyhyitä, pysyviä asioita, ei koskaan salaisuuksia. Kerro sitten muutamalla rivillä, mitä tallensit.",
  "Gets its own agent key: read and write nodes over MCP": "Saa oman agenttiavaimen: lukee ja kirjoittaa solmuja MCP:n yli",
  "Getting started": "Aloittaminen",
  "GitHub answered HTTP {code}": "GitHub vastasi HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Anna Claudelle, Cursorille tai muulle MCP-sovellukselle oma avain ja anna sen tallentaa, mitä se jo tietää sinusta.",
  "Give a key read-only access, or let it write too.": "Anna avaimelle vain lukuoikeus tai salli sen kirjoittaa myös.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Anna jokaiselle sovellukselle tai laitteelle oma agentti. Toiminta näyttää silloin tarkalleen kuka teki mitä, ja voit kytkeä yhden pois koskematta muihin.",
