  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Kuinka paljon tilaa muistiinpanot, kuvat ja Mnemo-keskustelut vievät, kukin omaan tilaansa verrattuna. Banneri varoittaa, kun yksi on lähes täynnä.",
