  "Humanist": "Humanistinen",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Etsin, luen, kirjoitan, merkitsen, linkitän ja siistin muistiinpanojasi. Ei verkkoa, ei komentotulkkia: vain holvisi.",
