  "Idle": "Lepää",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Jos siitä on ollut sinulle hyötyä, tähti GitHubissa tai maininta ystävälle auttaa muita löytämään sen. Ei hätää, jos ei.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Jos poistut, ne säilytetään tällä laitteella ja tarjotaan uudelleen, kun avaat muistiinpanon.",
