  "Images in this folder": "Tämän kansion kuvat",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Kuvat sijaitsevat niitä näyttävien muistiinpanojen vieressä. Valitse, kuinka suuri yksi saa olla, ja katso, paljonko muistiinpanot ja kuvat vievät.",
  "Import and export": "Tuonti ja vienti",
  "Imported": "Tuotu",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Avaa ChatGPT:ssä <b>Settings → Apps &amp; Connectors → Advanced settings</b> ja kytke päälle <b>Developer mode</b>. Valitse sitten <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Avaa Claudessa (web tai työpöytä) <b>Settings → Connectors</b> ja valitse <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Avaa Claude Desktopissa <b>Settings → Developer → Edit Config</b>. Uudemmissa versioissa valitse sen sijaan <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Avaa Windsurfissa <b>Settings → Cascade → MCP servers</b> ja valitse <b>View raw config</b>.",
