  "Internet (tunnel)": "Internet (tunneli)",
  "Internet address (IP)": "Internet-osoite (IP)",
  "It becomes your first rule.": "Siitä tulee ensimmäinen sääntösi.",
  "It becomes {path}. Links to its notes keep working.": "Siitä tulee {path}. Sen muistiinpanojen linkit toimivat edelleen.",
  "It can change notes, but nothing lets it connect.": "Se voi muuttaa muistiinpanoja, mutta mikään ei anna sen yhdistää.",
  "It can search and read your notes, but not change them": "Se voi hakea ja lukea muistiinpanojasi, mutta ei muuttaa niitä",
  "It can search, read and save your notes": "Se voi hakea, lukea ja tallentaa muistiinpanojasi",
  "It can {list}.": "Se voi {list}.",
  "It cannot do anything yet": "Se ei vielä voi tehdä mitään",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Sillä on täysi hallinta: se lukee ja muuttaa muistiinpanoja ja voi hallita Memoraa ja muita agentteja",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Siinä on {n} muistiinpano. Seuraavaksi valitset, mitä niille tapahtuu: siirrä ne toiseen kansioon tai Roskakoriin. Mitään ei ole vielä muutettu.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Siinä on {n} muistiinpanoa. Seuraavaksi valitset, mitä niille tapahtuu: siirrä ne toiseen kansioon tai Roskakoriin. Mitään ei ole vielä muutettu.",
  "It is added at the end, as rule {n}, so it is checked last.": "Se lisätään loppuun säännöksi {n}, joten se tarkistetaan viimeisenä.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Kaikki katoaa, kun lähdet, myös kuvat. Muistiinpanojen muutokset näkyvät yhä Toiminnassa ja Historiassa.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Se pidetään lukittuna palvelimella. Anna Memora-salasanasi, niin alla olevat painikkeet syöttävät sen puolestasi.",
  "It is taking a while. Check the server, then reload this page.": "Tämä kestää hetken. Tarkista palvelin ja lataa sitten tämä sivu uudelleen.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Se poistuu vain Kiinnitetyt-listasta; kansio itse pysyy paikallaan.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Se poistuu vain Kiinnitetyt-listasta; muistiinpano itse pysyy paikallaan.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Se on voitu nimetä uudelleen, siirtää tai poistaa. Poistetut muistiinpanot odottavat Roskakorissa.",
  "It moves; links to it are updated and pins follow.": "Se siirtyy; linkit siihen päivitetään ja kiinnitykset seuraavat.",
  "It must sign in again and is told why": "Sen on kirjauduttava uudelleen ja sille kerrotaan syy",
  "It prints a one-time code. This page moves on by itself.": "Se tulostaa kertakäyttökoodin. Tämä sivu etenee itse.",
  "It reached Memora but did not finish. It often works on the next try.": "Se tavoitti Memoran mutta ei valmistunut. Se toimii usein seuraavalla yrityksellä.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Se tavoitti Memoran mutta ei valmistunut: {error} Se toimii usein seuraavalla yrityksellä.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Se näkyy tällä nimellä Toiminnassa, aivoissa ja graafissa. Nimeä se laitteen mukaan, kun käytät {app}ia useammassa paikassa, esim. \"{example}\".",
  "It was shown when it was made. Make a new key to see one again.": "Se näytettiin, kun se luotiin. Luo uusi avain nähdäksesi sellaisen uudelleen.",
  "Italic": "Kursiivi",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "Sen API-avain ja mallit poistetaan. Keskustelut säilyvät; keskustelu, joka käytti yhtä sen malleista, vaihtuu oletukseen.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Sen avain ja käyttö pysyvät samoina jokaisessa muistiinpanokansiossa. Yhdistä toinen milloin vain.",
  "Its key is filled in on the next step": "Sen avain täytetään seuraavassa vaiheessa",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Sen avain hylätään, kunnes kytket sen takaisin päälle. Mitään ei poisteta.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Sen avain hylätään. Kytke se päälle, jotta se voi yhdistää uudelleen samalla avaimella.",
  "Its key stopped working. You can restore it until you reload the app.": "Sen avain lakkasi toimimasta. Voit palauttaa sen, kunnes lataat sovelluksen uudelleen.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Sen avain lakkaa toimimasta heti. Aiempi toiminta säilyy; voit palauttaa sen, kunnes lataat sovelluksen uudelleen.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Sen avain näytettiin vain kerran, kun se luotiin. Uusi avain korvaa sen ja vanha lakkaa toimimasta heti.",
  "Its notes are in its folders. You can also start one here.": "Sen muistiinpanot ovat sen kansioissa. Voit myös aloittaa sellaisen tässä.",
  "Its numbers, timeline and export.": "Sen luvut, aikajana ja vienti.",
  "Its old folder is not known, so it goes to the top level": "Sen vanhaa kansiota ei tiedetä, joten se menee ylätasolle",
  "Its page": "Sen sivu",
  "Its page shows how to connect it.": "Sen sivu näyttää, miten se yhdistetään.",
  "Its page: status, recent calls, access and settings.": "Sen sivu: tila, viimeisimmät kutsut, käyttö ja asetukset.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Sen oikeudet ovat mukautettu sekoitus. Valitse taso korvataksesi ne tai hienosäädä ne kohdassa Lisäasetukset.",
