  "Let in or keep out addresses and networks before anyone sees the sign-in page.": "Päästä sisään tai pidä ulkona osoitteita ja verkkoja ennen kuin kukaan näkee kirjautumissivun.",
  "Let it connect again with the same key.": "Anna sen yhdistää uudelleen samalla avaimella.",
  "Let it in. People still sign in and AIs still need their key.": "Päästä sisään. Ihmiset kirjautuvat silti ja tekoälyt tarvitsevat silti avaimensa.",
