  "Let's fill your memory": "Täytetään muistisi",
  "Lets the app use Memora's tools (MCP), limited by the tool list below. Every AI app needs this.": "Antaa sovelluksen käyttää Memoran työkaluja (MCP) alla olevan työkalulistan rajoissa. Jokainen tekoälysovellus tarvitsee tämän.",
