  "Locks, mentions and assignments so agents do not overwrite each other.": "Lukot, maininnat ja tehtävänannot, jotta agentit eivät ylikirjoita toisiaan.",
  "Long chats, light": "Pitkät keskustelut, kevyesti",
  "Long enough. A few more characters make it stronger.": "Tarpeeksi pitkä. Muutama merkki lisää vahvistaa sitä.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Pidemmät tehtävät näkyvät tarkistuslistana viestikentän yläpuolella: ei aloitettu, kesken, valmis.",
  "Longest sign-in": "Pisin kirjautuminen",
  "Longest sign-in must be at least the inactivity time": "Pisimmän kirjautumisen on oltava vähintään passiivisuusajan pituinen",
  "Look for tags that mean the same thing": "Etsi tunnisteita, joilla on sama merkitys",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Käy läpi tämän kansion projekti ja tallenna se Memoraan: mihin se on tarkoitettu, miten se on rakennettu, miten se ajetaan, tekniset päätökset ja kaikki muistamisen arvoinen. Tee yksi muistiinpano aihetta kohti kansioon, joka on nimetty projektin mukaan Projects-kansion sisällä.",
