  "Make a new key for {name} first": "Luo ensin uusi avain kohteelle {name}",
  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Luo agentti jokaiselle käyttämällesi sovellukselle tai laitteelle. Jokainen saa oman avaimen, joten näet mitä se tekee ja voit kytkeä sen pois erikseen.",
  "Make an index note for my biggest folder": "Tee hakemistomuistiinpano suurimmalle kansiolleni",
