  "Maybe you meant": "Ehkä tarkoitit",
  "Maybe you meant:": "Ehkä tarkoitit:",
  "Measuring…": "Mitataan…",
  "Medium": "Keskikokoinen",
  "Medium text": "Keskikokoinen teksti",
  "Meet Mnemo, your notes agent": "Tapaa Mnemo, muistiinpanoagenttisi",
  "Memora address (MCP endpoint)": "Memoran osoite (MCP-päätepiste)",
  "Memora already uses this folder.": "Memora käyttää jo tätä kansiota.",
  "Memora by Codrihub Tech": "Memora, Codrihub Tech",
  "Memora can save notes here": "Memora voi tallentaa muistiinpanoja tänne",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora tarkistaa kansion ja pyytää vahvistamaan ennen vaihtoa. Mitään ei siirretä tai kopioida, ja voit vaihtaa takaisin tässä. Ajatko Dockerissa? Käytä konttiin liitettyä kansiota.",
  "Memora could not start.": "Memoraa ei voitu käynnistää.",
  "Memora data folder": "Memoran datakansio",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora tarkistaa ensin, että uusi kansio on olemassa (tai sen voi luoda) ja että sinne voi tallentaa muistiinpanoja. Jos tarkistus epäonnistuu, mikään ei muutu.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora tarkistaa ensin, että uusi kansio on olemassa ja että sinne voi tallentaa muistiinpanoja. Jos tarkistus epäonnistuu, mikään ei muutu.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora omalla kielelläsi, Mnemo näyttää suunnitelmansa työskennellessään, ja sinä valitset, mitä se saa käyttää ja nähdä.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora on muistiinpanosovellus, jota myös tekoälysovelluksesi voivat käyttää. Sinä kirjoitat siinä, ne lukevat ja kirjoittavat samoja muistiinpanoja, ja näet aina mikä muuttui.",
  "Memora is free and open source": "Memora on ilmainen ja avoimen lähdekoodin",
  "Memora is free and open source. A star helps others find it.": "Memora on ilmainen ja avoimen lähdekoodin. Tähti auttaa muita löytämään sen.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora on muisti, edistyneenä: rakennettu muistamaan, mitä sinä ja tekoälysi opitte, ja muistamaan enemmän, mitä enemmän käytät sitä.",
  "Memora is restarting": "Memora käynnistyy uudelleen",
  "Memora is shut down": "Memora on sammutettu",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora on vielä tyhjä. Yhdistä tekoälysovellus, lähetä sille yksi kehote, ja se tallentaa tietämänsä sinusta tänne muistiinpanoina, joita voit lukea, muokata ja katsoa aivoissa.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora pitää listaa tunnisteistasi ehdottaakseen niitä kirjoittaessasi. Päivitä se, jos tunniste puuttuu tai on vanhentunut.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora säilyttää muistiinpanon jokaisen version, kun holvikansio on git-repositorio. Aja {cmd} holvikansiossa kerran (katso Configuration, “Version history” dokumentaatiosta); siitä lähtien jokainen muutos säilytetään täällä.",
  "Memora keeps it in one place:": "Memora säilyttää sen yhdessä paikassa:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora tallentaa jokaisen muistiinpanon tavallisena Markdown-tiedostona koneelle, jolla se pyörii. Mikään ei ole lukittuna: avaa tiedostot missä tahansa editorissa, varmuuskopioi ne tai pidä ne Gitissä.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora puhuu MCP:tä streamattavan HTTP:n yli. Sovellukset lähettävät avaimen otsikossa <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora pysähtyy koneella, jolla se pyörii. Muistiinpanosi pysyvät turvassa levyllä.",
  "Memora version": "Memoran versio",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} on saatavilla. Tämä palvelin ajaa versiota v{current}.",
  "Memora, open Overview": "Memora, avaa Yleiskatsaus",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: itse ylläpidetty muistiinpanoholvi, jota agentti siistii.",
  "Memory used: {used} of {win}": "Muistia käytetty: {used} / {win}",
  "Mentioned in": "Mainittu kohteessa",
  "Mentions": "Maininnat",
  "Merge": "Yhdistä",
  "Merge into": "Yhdistä kohteeseen",
  "Merge {n} tags": "Yhdistä {n} tunnistetta",
  "Merged": "Yhdistetty",
  "Merged a duplicate": "Yhdisti kaksoiskappaleen",
  "Merged notes": "Yhdistetyt muistiinpanot",
  "Merged tags": "Yhdistetyt tunnisteet",
  "Merged {tags} into #{into} · {notes} changed": "Yhdisti {tags} tunnisteeseen #{into} · {notes} muuttui",
