  "Message copied": "Viesti kopioitu",
  "Message to {mnemo}": "Viesti {mnemo}lle",
  "Messaged {agent}": "Viestitti {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Viestit ja viestikenttä ovat tarkalleen linjassa joka leveydellä, mallinvalitsimella on oma pintansa, hetkellinen keskustelu sopii puhelimeen eikä kysymyksen vaihtoehdot enää liu'u pois napautettaessa.",
  "Middle-drag": "Keskipainikevedolla",
  "Midnight": "Keskiyö",
  "Minimap": "Minikartta",
  "Minimap: click or drag to move the view": "Minikartta: siirrä näkymää napsauttamalla tai vetämällä",
  "Mist": "Usva",
  "Mnemo (AI agent)": "Mnemo (tekoälyagentti)",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo-painike piilotettu. Näytä se uudelleen kohdasta Lisää, Näytä Mnemo-painike.",
  "Mnemo goes on without sub-agents": "Mnemo jatkaa ilman aliagentteja",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemolla ei ole vielä mallia: lisää palveluntarjoaja ja sen mallit kohdassa Asetukset, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo on rakennettu Memoraan. Yhdistä oma tekoälyavaimesi ja kysy tavallisin sanoin: se etsii, kirjoittaa, merkitsee, linkittää ja siistii muistiinpanoja puolestasi.",
  "Mnemo is still answering in this chat": "Mnemo vastaa vielä tässä keskustelussa",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo on Memoraan sisäänrakennettu agentti. Yhdistä oma tekoälyavaimesi ja pyydä tavallisin sanoin: se pitää muistiinpanosi järjestyksessä, kun muut sovelluksesi käyttävät niitä.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo säilyttää enintään {n} palveluntarjoajaa; poista ensin yksi",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo hallitsee aliagenttejaan, pitää suunnitelmansa keskustelussa, ja keskustelu sopii paremmin jokaiselle näytölle.",
  "Mnemo runs its sub-agents": "Mnemo ohjaa aliagenttejaan",
