  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Ei tehty: Mnemo on Kysy ensin -tilassa, joten muutokset odottavat omistajan hyväksyntää. Kysy ask_owner-työkalulla (kerro, mitä aiot muuttaa; anna vaihtoehto approve: true, kuten \"Yes, go ahead\"), ja tee muutos vasta kun hän hyväksyy.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Ei tehty: Mnemo on Vain luku -tilassa, joten muistiinpanoja ei muuteta. Kerro, mitä muuttaisit; omistaja voi vaihtaa tilaksi Kysy ensin tai Auto keskustelussa.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Ei tehty: keskustelu on Kysy ensin -tilassa, joten aliagentti ei voi muuttaa muistiinpanoja. Kerro vastauksessasi, mitä pitäisi muuttaa; Mnemo kysyy omistajalta.",
