  "Noted about you: {text}": "Merkitty sinusta: {text}",
  "Noted something about you": "Merkitsi jotain sinusta",
  "Notes": "Muistiinpanot",
  "Notes and images in the notes folder.": "Muistiinpanot ja kuvat muistiinpanokansiossa.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Muistiinpanot ja niiden väliset linkit näkyvät täällä karttana. Opas näyttää, miten tekoäly tallentaa tietonsa tänne tai miten kirjoitat muistiinpanon itse.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Muistiinpanot ilmestyvät, kun tekoäly tallentaa ne, ja sytyttävät aivot. Tämä sivu muuttuu kojelaudaksesi, kun ensimmäinen muistiinpano saapuu.",
  "Notes are not a password manager.": "Muistiinpanot eivät ole salasanamanageri.",
  "Notes changed in the app or in the folder": "Sovelluksessa tai kansiossa muuttuneet muistiinpanot",
  "Notes folder": "Muistiinpanokansio",
  "Notes folder switched": "Muistiinpanokansio vaihdettu",
  "Notes from {name}": "Muistiinpanot lähteestä {name}",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Nykyisen kansion muistiinpanoja ei siirretä, kopioida tai poisteta. Voit vaihtaa takaisin tässä milloin tahansa.",
  "Notes inside a folder": "Kansion sisällä olevat muistiinpanot",
  "Notes it found": "Sen löytämät muistiinpanot",
  "Notes it saved": "Sen tallentamat muistiinpanot",
  "Notes must carry": "Muistiinpanoilla on oltava",
  "Notes tagged #{tag}": "Muistiinpanot tunnisteella #{tag}",
  "Notes that carry at least one tag": "Muistiinpanot, joilla on vähintään yksi tunniste",
  "Notes that carry every tag": "Muistiinpanot, joilla on jokainen tunniste",
  "Notes that link nowhere and are linked from nowhere.": "Muistiinpanot, jotka eivät linkitä minnekään eikä niihin linkitetä mistään.",
  "Notes touched": "Käsitellyt muistiinpanot",
  "Notes with a tag; the start of the tag is enough": "Muistiinpanot, joilla on tunniste; tunnisteen alku riittää",
  "Notes you delete wait here, so you can bring them back.": "Poistamasi muistiinpanot odottavat täällä, jotta voit tuoda ne takaisin.",
  "Notes you or your AIs write show up here, newest first.": "Sinun tai tekoälyjesi kirjoittamat muistiinpanot näkyvät täällä, uusin ensin.",
  "Notes, folders and images in this chat": "Muistiinpanot, kansiot ja kuvat tässä keskustelussa",
  "Nothing deleted": "Mitään ei poistettu",
  "Nothing else in the last 24 hours.": "Ei muuta viimeisen 24 tunnin aikana.",
  "Nothing from {name} in the last 24 hours.": "Ei mitään lähteestä {name} viimeisen 24 tunnin aikana.",
  "Nothing here": "Ei mitään täällä",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Mitään ei ole vielä piilotettu: valitse agentit, joilta piilotat sen. Tällä hetkellä kaikki {n} agenttia näkevät sen.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Mitään ei ole vielä piilotettu: valitse agentit, joilta piilotat sen. Tällä hetkellä ainoa agentti näkee sen.",
  "Nothing in 24h": "Ei mitään 24 tunnissa",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Ei mitään muistiinpanojen nimissä, kansioissa tai teksteissä, eikä mitään sen lähellä kirjoitettua. Kokeile vähemmän kirjaimia, toista kirjoitusasua tai sanaa muistiinpanon sisältä.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Ei mitään viimeisen 24 tunnin aikana. Se, mitä tekoälysi tekevät, näkyy täällä sitä mukaa kun se tapahtuu.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Mikään lokissa ei ole nimellä “{name}”. Näytetään kaikki toiminta.",
  "Nothing in this range": "Ei mitään tällä aikavälillä",
  "Nothing in your chats says “{query}”.": "Mikään keskusteluissasi ei sano “{query}”.",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "Mitään ei sallita. Kytke jotain päälle tai keskeytä agentti sen sijaan.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Mitään ei menetetä: nykyinen teksti säilyy historiassa versiona v{n}, joten voit vaihtaa takaisin milloin tahansa.",
  "Nothing links here yet.": "Tänne ei linkitetä vielä mistään.",
  "Nothing matches": "Mikään ei täsmää",
  "Nothing matches with these filters.": "Mikään ei täsmää näillä suodattimilla.",
