  "Nothing matches “{q}”.": "Mikään ei täsmää haulla “{q}”.",
  "Nothing matches “{q}”. Maybe you meant one of these:": "Mikään ei täsmää haulla “{q}”. Ehkä tarkoitit jotain näistä:",
  "Nothing matches.": "Mikään ei täsmää.",
  "Nothing needs you right now.": "Mikään ei tarvitse sinua juuri nyt.",
  "Nothing recorded from this device yet.": "Tältä laitteelta ei ole vielä tallennettu mitään.",
  "Nothing said here is kept.": "Mitään täällä sanottua ei tallenneta.",
  "Nothing to compact yet": "Ei vielä mitään tiivistettävää",
  "Nothing to delete": "Ei mitään poistettavaa",
  "Nothing to save": "Ei mitään tallennettavaa",
  "Nothing to undo": "Ei mitään kumottavaa",
  "Nothing to undo: “{title}” is not pinned already.": "Ei mitään kumottavaa: “{title}” ei ole jo kiinnitetty.",
  "Nothing to undo: “{title}” is pinned already.": "Ei mitään kumottavaa: “{title}” on jo kiinnitetty.",
  "Nothing was heard": "Mitään ei kuultu",
