  "Now": "Nyt",
  "Now ask {name} to save what it knows": "Pyydä nyt {name}ia tallentamaan, mitä se tietää",
  "Nudge": "Tönäise",
  "OK": "OK",
  "Off": "Pois",
  "Off for every AI.": "Pois päältä kaikilta tekoälyiltä.",
  "Off for every agent": "Pois päältä kaikilta agenteilta",
  "Off: its models are hidden in chats": "Pois: sen mallit piilotetaan keskusteluissa",
  "Off: tap to switch on": "Pois: napauta kytkeäksesi päälle",
  "Offline": "Offline",
  "Offline · Memora": "Offline · Memora",
  "Offline, retrying": "Offline, yritetään uudelleen",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Vanhempi Gemini CLI ilman komentoa <code>gemini mcp add</code>: lisää palvelin tiedostoon <code>~/.gemini/settings.json</code> avaimen <code>mcpServers</code> alle, käyttäen <code>httpUrl</code>-kenttää ja samaa otsikkoa.",
  "Older changes stay in History.": "Vanhemmat muutokset säilyvät Historiassa.",
  "Older messages were left out to fit the model's context.": "Vanhemmat viestit jätettiin pois mahtuakseen mallin kontekstiin.",
  "Older than 30 days": "Yli 30 päivää vanhat",
  "Older than 7 days": "Yli 7 päivää vanhat",
  "Older than 90 days": "Yli 90 päivää vanhat",
  "Older versions of a note: read, compare, restore, and the trash.": "Muistiinpanon vanhemmat versiot: lue, vertaa, palauta, sekä roskakori.",
  "Oldest entry": "Vanhin merkintä",
  "On": "Päällä",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Tietokoneella vedä keskustelulistan tai sivupaneelin reunaa leventääksesi tai kaventaaksesi sitä. Jokaisella on vähimmäisleveys, ja se muistaa leveytensä.",
  "On its avatar, its sparks in the brain and every activity row.": "Sen avatarissa, sen kipinöissä aivoissa ja jokaisella toimintarivillä.",
  "On this page": "Tällä sivulla",
  "On: tap to switch off": "Päällä: napauta kytkeäksesi pois",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Päällä: {mnemo} merkitsee muistiin, mitä se poimii keskusteluista. Pois: vain se, minkä lisäät tähän. Tallentuu heti.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Asennettuna sovelluksella on oma kuvake, se avautuu koko näytölle ja on tavoitettavissa verkon katkettua.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Kun se on yhdistetty, liitä tämä uuteen keskusteluun kyseisessä sovelluksessa. Se käskee tekoälyä tallentamaan tietämänsä Memoraan.",
  "Once its app is set up, every call shows up here as it happens.": "Kun sen sovellus on asetettu, jokainen kutsu näkyy täällä sitä mukaa kun se tapahtuu.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Kun {name} on yhdistetty, kaikki, mitä se lukee, kirjoittaa ja hakee, näkyy täällä livenä.",
  "One address": "Yksi osoite",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Yksi agentti sovellusta tai laitetta kohti: oma avain, oma nimi Toiminnassa, kytkettävissä pois erikseen.",
  "One click": "Yksi napsautus",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Yksi laite tai yhteys, kuten 203.0.113.7. Haulla \"what is my IP\" näet omasi.",
  "One device or connection.": "Yksi laite tai yhteys.",
  "One folder of notes that you and every connected AI share.": "Yksi muistiinpanokansio, jota sinä ja jokainen yhdistetty tekoäly jaatte.",
  "One is hidden by the folder rule.": "Yksi on piilotettu kansiosäännöllä.",
  "One key per agent, its own permissions.": "Yksi avain agenttia kohti, omat oikeudet.",
  "One last step": "Viimeinen vaihe",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Yksi muisti, jota jokainen agentti lukee ja kirjoittaa ja jonka kaiken voit nähdä, muokata ja yhdistää.",
  "One memory for every AI": "Yksi muisti jokaiselle tekoälylle",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Yksi muistiinpano näyttää tämän kuvan; se näkyy siellä puuttuvana. Versiohistoria säilyttää sen.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Yksi riviä kohti. Ne näkyvät ehdotusten joukossa uudessa keskustelussa merkittynä Omat ja pysyvät, kunnes muutat niitä.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Yksi yksityinen muisti, jota sinä ja tekoälysovelluksesi jaatte, jotta mitään ei tarvitse selittää kahdesti.",
  "One set of notes for every AI app": "Yksi muistiinpanojen joukko jokaiselle tekoälysovellukselle",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "Vain PNG-, JPEG-, WebP- ja GIF-kuvia voi lisätä",
  "Only in the current version": "Vain nykyisessä versiossa",
  "Only in version {n}": "Vain versiossa {n}",
  "Only letters, digits and - _ / . can be used.": "Vain kirjaimia, numeroita ja - _ / . voi käyttää.",
  "Only looks at notes; changes nothing.": "Katsoo vain muistiinpanoja; ei muuta mitään.",
  "Only looks things up and never writes. For agents with a read-only key.": "Hakee vain eikä kirjoita koskaan. Agenteille, joilla on vain luku -avain.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Vain uusimman viestisi kuvat menevät kuvamallille, ja kuulet siitä lyhyellä ilmoituksella.",
  "Only reads and answers; never changes notes": "Lukee ja vastaa vain; ei koskaan muuta muistiinpanoja",
  "Only the agents you pick. New agents can’t see it.": "Vain valitsemasi agentit. Uudet agentit eivät näe sitä.",
  "Only the first rule that fits a request counts.": "Vain ensimmäinen pyyntöön sopiva sääntö lasketaan.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Aluksi sivulle tulevat vain uusimmat kysymykset; vanhemmat tulevat, kun vierität ylös tai hyppäät niihin aikajanalta.",
  "Only the ones I pick": "Vain valitsemani",
