  "Only this agent": "Vain tämä agentti",
  "Only {names} can see this {what}. Every other agent, including ones added later, is blocked.": "Vain {names} näkevät tämän: {what}. Kaikki muut agentit, myöhemmin lisätyt mukaan lukien, on estetty.",
