  "Operations": "Toiminnot",
  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Valinnainen. Muutama sana siitä, kuka olet, mitä teet ja miten haluat vastaukset. {mnemo} muistaa ne ja voit muuttaa niitä milloin tahansa Asetuksissa.",
  "Or any emoji": "Tai mikä tahansa emoji",
