  "Other files in it (such as images) are deleted too. This cannot be undone.": "Muutkin sen tiedostot (kuten kuvat) poistetaan. Tätä ei voi kumota.",
  "Other servers in the file already? Add only the <code>memora</code> entry inside <code>mcpServers</code>.": "Onko tiedostossa jo muita palvelimia? Lisää vain <code>memora</code>-merkintä avaimen <code>mcpServers</code> sisään.",
