  "Pages {mnemo} writes, and the notes, folders and images this chat attaches, reads, changes or shows you collect here.": "Täällä kerätään sivut, jotka {mnemo} kirjoittaa, sekä muistiinpanot, kansiot ja kuvat, jotka tämä keskustelu liittää, lukee, muuttaa tai näyttää sinulle.",
