  "Password must be at least {min} characters.": "Salasanassa on oltava vähintään {min} merkkiä.",
  "Password saved. Opening your vault...": "Salasana tallennettu. Avataan holviasi...",
  "Password saved. Sign in with the new password.": "Salasana tallennettu. Kirjaudu uudella salasanalla.",
  "Passwords are reset on the server that runs Memora.": "Salasanat nollataan palvelimella, jolla Memora pyörii.",
  "Passwords do not match": "Salasanat eivät täsmää",
  "Passwords do not match.": "Salasanat eivät täsmää.",
  "Passwords match": "Salasanat täsmäävät",
  "Past activity keeps the old name; new activity uses this one.": "Aiempi toiminta säilyttää vanhan nimen; uusi toiminta käyttää tätä.",
  "Paste both into the app and save.": "Liitä molemmat sovellukseen ja tallenna.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Liitä se päätteeseen ja paina <kbd>Enter</kbd>, käynnistä sitten Codex samassa päätteessä.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Liitä se päätteeseen ja paina <kbd>Enter</kbd>. Käynnistä sitten Claude Code tai käynnistä se uudelleen: Memora latautuu itse.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Liitä se päätteeseen ja paina <kbd>Enter</kbd>. Käynnistä sitten Gemini CLI tai käynnistä se uudelleen ja kirjoita <code>/mcp</code> nähdäksesi Memoran.",
  "Paste it into the app where it asks for a key.": "Liitä se sovellukseen kohtaan, jossa se kysyy avainta.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Liitä se tiedostoon ja tallenna, paina sitten <b>Refresh</b>. Memora ilmestyy listaan.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Liitä se tiedostoon, tallenna ja käynnistä Claude Desktop uudelleen. Se vaatii Node.js:n tälle tietokoneelle.",
  "Paste it into {app}": "Liitä se sovellukseen {app}",
  "Paste the API key": "Liitä API-avain",
  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "Liitä nämä kerran sinne, mistä {app} lukee pysyvät ohjeensa, jotta se käyttää Memoraa jokaisessa keskustelussa, ei vain pyydettäessä.",
