  "Pick it and the setup steps for that app follow, with {name}'s key filled in. For another app or device, make a new agent.": "Valitse se, niin sen sovelluksen asennusvaiheet seuraavat, kohteen {name} avain täytettynä. Toista sovellusta tai laitetta varten luo uusi agentti.",
