  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Tallenna Memoraan, mitä olen kertonut sinulle henkilökohtaisesta elämästäni: kiinnostuksenkohteeni, tapani, tavoitteeni, minulle tärkeät ihmiset ja asiat, joista välitän. Laita nämä muistiinpanot Private-nimiseen kansioon, yksi muistiinpano aihetta kohti, ja linkitä liittyvät muistiinpanot. Älä koskaan tallenna salasanoja, korttinumeroita tai muita salaisuuksia. Kun olet valmis, kerro minulle, mitä tallensit.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Tallenna Memoraan, mitä tiedät työstäni: roolini, tiimini, projektit, joissa olen mukana, ja missä ne ovat, sekä tekemämme päätökset. Tee yksi muistiinpano projektia tai aihetta kohti ja linkitä ne yhteen.",
