  "This note does not link to other notes yet. Type [[ while editing to add a link.": "Tämä muistiinpano ei linkitä vielä muihin muistiinpanoihin. Kirjoita [[ muokatessasi lisätäksesi linkin.",
  "This note has changes that are not saved yet.": "Tässä muistiinpanossa on vielä tallentamattomia muutoksia.",
  "This note has no headings yet.": "Tässä muistiinpanossa ei ole vielä otsikoita.",
  "This note has not been saved to the history yet. The next change starts it.": "Tätä muistiinpanoa ei ole vielä tallennettu historiaan. Seuraava muutos aloittaa sen.",
  "This note is empty.": "Tämä muistiinpano on tyhjä.",
  "This note is empty. {start} or press {key}.": "Tämä muistiinpano on tyhjä. {start} tai paina {key}.",
  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "Tämä muistiinpano poistetaan holvista lopullisesti tekstin, tunnisteiden ja linkkien kanssa. Myös kaikki aiemmat versiot poistetaan versiohistoriasta, joten kukaan, agentit mukaan lukien, ei voi lukea sitä enää.",
  "This note links to nothing yet.": "Tämä muistiinpano ei linkitä vielä mihinkään.",
