  "This page moves on by itself.": "Tämä sivu etenee itse.",
  "This page notices by itself as soon as {app} connects. Keep it open.": "Tämä sivu huomaa itse heti, kun {app} yhdistää. Pidä se auki.",
  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "Tätä palvelinta ajaa systemd, joka käynnistää sen uudelleen muutaman sekunnin kuluttua. Pitääksesi sen pysäytettynä aja palvelimella sen sijaan {cmd}.",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "Tämä palvelin pyörii Dockerissa, joka voi käynnistää sen uudelleen. Pitääksesi sen pysäytettynä aja isännällä sen sijaan {cmd}.",
