  "To-dos, follow-ups, checks that a note is well formed, and the pinned notes and folders.": "Tehtävät, jatkotoimet, tarkistukset että muistiinpano on hyvin muodostettu, sekä kiinnitetyt muistiinpanot ja kansiot.",
