  "Your connected AI works in this folder now. Ask one to save what it knows here, or write a note yourself. Switched folders by mistake? Switch back under Settings, Notes folder.": "Yhdistetty tekoälysi työskentelee nyt tässä kansiossa. Pyydä jotakin tallentamaan tietonsa tänne tai kirjoita muistiinpano itse. Vaihdoitko kansiota vahingossa? Vaihda takaisin kohdassa Asetukset, Muistiinpanokansio.",
