  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} toimii vain muistiinpanoissasi. Jokainen muutos näkyy Toiminnassa ja sen voi kumota Historiasta.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} lukee holvisi uudessa keskustelussa ja säilyttää oppimansa täällä.",
  "{mnemo} settings saved": "{mnemo}-asetukset tallennettu",
  "{mnemo} settings: models and keys": "{mnemo}-asetukset: mallit ja avaimet",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} käynnistää aliagentteja itse, kun tehtävä jakautuu hyvin; mitään ei tarvitse asettaa. Ne käyttävät oletusmalliasi, sitten varamalleja, ellet nimeä mallia keskustelussa. Seuraa niitä ja vaihda niiden mallia kohdassa Agentit keskustelun oikeassa yläkulmassa. Ne käyttävät omia tokeneitaan, joten Kysy ensin -tilassa {mnemo} kysyy ja kertoo suunnilleen kuinka paljon; Auto-tilassa ne vain ajetaan. Tallentuu heti.",
  "{mnemo} stopped it": "{mnemo} pysäytti sen",
