  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} ei näe kuvia; se sai niiden nimet sen sijaan. Aseta kuvia lukeva malli Asetuksissa, jotta ne nähdään.",
  "{model} cannot look at images; the image model described them for it.": "{model} ei näe kuvia; kuvamalli kuvaili ne sille.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} ei osaa lukea kuvia, joten se saa vain niiden nimet. Aseta kuvia lukeva malli tai vaihda tämän keskustelun mallia.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} ei osaa lukea kuvia, joten se sai vain niiden nimet. Aseta kuvia lukeva malli tai vaihda tämän keskustelun mallia.",
